const hello = document.querySelector("#hello");

function showGreeting() {
  // welcome back if a name is saved, otherwise hello
  const name = localStorage.getItem("pilot");
  hello.textContent = name ? `Welcome back, ${name}!` : "Hello, new pilot!";
}

// form: save; Forget: delete
document.querySelector("#name-form").addEventListener("submit", (e) => {
  e.preventDefault();
  const name = document.querySelector("#name").value.trim();
  if (name === "") return;
  localStorage.setItem("pilot", name);
  showGreeting();
});

document.querySelector("#forget").addEventListener("click", () => {
  localStorage.removeItem("pilot");
  showGreeting();
});

showGreeting();

