project_task.solution:
const bestEl = document.querySelector("#best");
const info = document.querySelector("#info");

function loadBest() {
  // return the saved record as a number (0 if missing)
  return Number(localStorage.getItem("best")) || 0;
}

function saveBest(score) {
  // if the record is beaten, save it and return true; otherwise false
  if (score <= loadBest()) return false;
  localStorage.setItem("best", String(score));
  bestEl.textContent = score;
  info.textContent = `New record: ${score}!`;
  return true;
}

// show the record when the page opens
bestEl.textContent = loadBest();
